import cv2import timefrom collections import defaultdictleft_side_car = set()counter_car = set()def tracking(frame, model, start_line, a_start_line):    results = model.track(        frame,        persist=True,        tracker="model/botsort.yaml",        imgsz=1280,        classes=[2],        conf=0.25,        verbose=False,    )[0]    # если в кадре вообще нет подтверждённых треков — просто отдаём кадр как есть    if results.boxes.id is None:        return frame    boxes = results.boxes.xyxy.cpu().tolist()    track_ids = results.boxes.id.int().cpu().tolist()    confidences = results.boxes.conf.cpu().tolist()    dict_car = defaultdict(list)    for box, track_id, confidence in zip(boxes, track_ids, confidences):        xmin, ymin, xmax, ymax = map(int, box)        x = int(xmin)        y = int(ymin)        width = int(xmax - xmin)        height = int(ymax - ymin)        cen_car = ((xmin + xmax) / 2, ymin)        # Если находится слева от линии и потом пересекает линию, то добавляем в счетчик        if cen_car[0]<start_line[0]:            left_side_car.add(track_id)        if cen_car[0]>=a_start_line[0]:            start_time =time.time()            dict_car[track_id].append(start_time)        if cen_car[0] >= start_line[0] and track_id in left_side_car:            counter_car.add(track_id)            end_time = time.time()            dict_car[track_id].append(end_time)        cv2.rectangle(frame, (x, y), (x + width, y + height), (0, 255, 0), 2)        cv2.putText(frame, str(track_id), (x, y), cv2.FONT_HERSHEY_SIMPLEX, 2, (0, 0, 255), 2)